SELECT id, order_id, amount, ROW_NUMBER() OVER w_grp AS event_seq, FIRST_VALUE(method, TRUE) OVER (PARTITION BY method ORDER BY amount, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_method, ROW_NUMBER() OVER w_grp AS row_seq, ROUND(amount / SUM(amount) OVER (PARTITION BY method), 4) AS amount_share, NTILE(3) OVER (PARTITION BY status ORDER BY amount DESC, id) AS amount_bucket FROM payments WINDOW w_grp AS (PARTITION BY status ORDER BY amount, id);
